@page "/chat"
@using sv_50477f8e944f4438bc9c2759d0006ee6.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <aside class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_selectedChannel?.Id ?? 0"
                     OnChannelSelected="SelectChannel" />
    </aside>

    <main class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_selectedChannel is not null)
        {
            <MessageArea Messages="_messages"
                         ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         ThreadReplyCounts="_threadReplyCounts"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="chat-thread-panel">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         Loading="_threadLoading"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </aside>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private bool _threadLoading;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await UpdateThreadCounts();
        CloseThread();
        StateHasChanged();
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null) return;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            await UpdateThreadCounts();
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
        }
    }

    private async Task OpenThread(Message message)
    {
        _threadRootMessage = message;
        _threadOpen = true;
        _threadLoading = true;
        StateHasChanged();

        _threadReplies = await ChatService.GetThreadAsync(message.Id);
        _threadLoading = false;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadReplies.Count;
    }

    private async Task UpdateThreadCounts()
    {
        _threadReplyCounts.Clear();
        // Count replies for each root message (messages with replies pointing to them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var msg in _messages.Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value)))
        {
            var rootId = msg.ReplyToId!.Value;
            _threadReplyCounts[rootId] = _threadReplyCounts.GetValueOrDefault(rootId) + 1;
        }

        // Also fetch thread info for messages that might have replies not loaded
        foreach (var msg in _messages.Where(m => m.ReplyToId is null))
        {
            if (!_threadReplyCounts.ContainsKey(msg.Id))
            {
                var thread = await ChatService.GetThreadAsync(msg.Id);
                if (thread.Count > 0)
                {
                    _threadReplyCounts[msg.Id] = thread.Count;
                }
            }
        }
    }
}

